using System.Text.Json;
using DynastyManager.Core.Models;
using DynastyManager.Core.Simulation;
using DynastyManager.Data.Import;
using ProFootball.Core;
var mode=args.ElementAtOrDefault(0)??"pro-real";var count=int.Parse(args.ElementAtOrDefault(1)??"128");var output=args.ElementAtOrDefault(2)??".artifacts/balance.json";
if(mode.EndsWith("seasons")){await SeasonAudit.Run(mode,count,output);return;}
var baselinePacing=args.ElementAtOrDefault(3)=="baseline-pacing";
var pro=mode.StartsWith("pro");var random=new Random(20261029);IReadOnlyList<DynastyPlayer> roster;Dictionary<string,TeamSimulationProfile> profiles;
if(pro){var s=ProLeagueService.Create("Seattle Seahawks");if(mode.EndsWith("generated"))s=s with{Players=ProGeneratedRoster.Create(s.League,new Random(12345))};roster=s.Players.Where(p=>ProDepthChart.Active(p)&&ProReserve.MedicallyAvailable(s,p)).Select(p=>p.Football).ToArray();profiles=s.League.Teams.ToDictionary(t=>t.Name,t=>ProLeagueService.Profile(s,t.Name));}
else{var teams=ModernFbsUniverseFactory.Create(LegacyUniverseCsvImporter.Import(File.ReadAllText("src/DynastyManager.Data/Resources/Legacy/universe.csv")).Teams).ToArray();using var reader=File.OpenText("src/DynastyManager.App/Resources/Raw/next26-aug26-2025.csv");roster=Next26RosterCsvImporter.LoadPack(reader,teams.Select(t=>t.Name)).Players;var state=new DynastyState{DynastyName="Audit",UserTeamName="Washington",ActiveRoster=roster};if(mode.EndsWith("generated")){roster=FictionalRosterService.College(roster,teams,new Random(12345));state=state with{ActiveRoster=roster};}profiles=DynastyRosterSimulationProfileBuilder.Build(state,teams).ToDictionary(p=>p.Key,p=>p.Value);}
var names=profiles.Keys.Order().ToArray();var games=new List<ScheduledGame>();var qbShares=new List<double>();var rbShares=new List<double>();var rb3=new List<double>();var dlShares=new List<double>();var teamPlays=new List<int>();var malformed=0;var duplicate=0;var badExamples=new List<string>();
for(var i=0;i<count;i++){
 var home=names[i%names.Length];var away=names[(i%names.Length+1+random.Next(names.Length-1))%names.Length];var g=new ScheduledGame{GameId="audit-"+i,SeasonYear=2026,Week=1,HomeTeamName=home,AwayTeamName=away,SimulationSeed=1000+i*7919};
 var session=GameDayEngine.Start(g,profiles[home],profiles[away],roster,GameDayMode.Simulate,rules:pro?(baselinePacing?FootballRules.Professional with {NormalPreSnapMinimumSeconds=31,NormalPreSnapMaximumSeconds=37}:FootballRules.Professional):FootballRules.College);GameDayEngine.SimulateToEnd(session);games.Add(GameDayEngine.Finish(session));
 foreach(var team in new[]{home,away}){
 var plays=session.Events.Where(e=>e.OffenseTeamName==team&&GameDayEngine.IsScrimmage(e)).ToArray();teamPlays.Add(plays.Length);
 var qbs=plays.Where(e=>e.QuarterbackId!=null).GroupBy(e=>e.QuarterbackId).Select(x=>x.Count()).OrderDescending().ToArray();qbShares.Add(qbs.Length==0?0:qbs[0]/(double)qbs.Sum());
 var carries=plays.Where(e=>e.BallCarrierId is Guid id&&session.PlayersById[id].Position==Position.RB&&e.Outcome is SnapOutcome.Run or SnapOutcome.Touchdown or SnapOutcome.Fumble).GroupBy(e=>e.BallCarrierId).Select(x=>x.Count()).OrderDescending().ToArray();if(carries.Length>0){rbShares.Add(carries[0]/(double)carries.Sum());rb3.Add(carries.Skip(2).Sum()/(double)carries.Sum());}
 var defense=session.Events.Where(e=>e.DefenseTeamName==team&&GameDayEngine.IsScrimmage(e)).ToArray();var depth=PersonnelRotationService.BuildDepthChart(session.Roster,team);var dlStarters=new[]{Position.DE,Position.DT}.SelectMany(pos=>depth.GetValueOrDefault(pos,[]).Take(2)).Select(p=>p.PlayerId).ToHashSet();var dl=defense.SelectMany(e=>e.DefensePersonnel).Where(id=>session.PlayersById[id].Position is Position.DE or Position.DT).ToArray();dlShares.Add(dl.Length==0?0:dl.Count(id=>!dlStarters.Contains(id))/(double)dl.Length);
 }
 foreach(var e in session.Events.Where(GameDayEngine.IsScrimmage)){if(e.OffensePersonnel.Count!=11||e.DefensePersonnel.Count!=11){malformed++;if(badExamples.Count<8)badExamples.Add($"{e.Outcome} {e.OffensivePlayId} {e.DefensivePlayId} {e.OffensePersonnel.Count}/{e.DefensePersonnel.Count}");}if(e.OffensePersonnel.Distinct().Count()!=e.OffensePersonnel.Count||e.DefensePersonnel.Distinct().Count()!=e.DefensePersonnel.Count)duplicate++;}
}
var stats=games.SelectMany(g=>new[]{g.HomeStats!,g.AwayStats!}).ToArray();double Mean(Func<GameTeamStats,int> f)=>stats.Average(f);
var report=new{Mode=mode,BaselinePacing=baselinePacing,Games=count,TeamGames=stats.Length,Points=games.Average(g=>(g.HomeScore!.Value+g.AwayScore!.Value)/2d),Plays=teamPlays.Average(),Yards=Mean(s=>s.TotalYards),Passing=Mean(s=>s.PassYards),Rushing=Mean(s=>s.RushYards),CompletionPct=100d*stats.Sum(s=>s.PassCompletions)/stats.Sum(s=>s.PassAttempts),YardsPerPass=stats.Sum(s=>s.PassYards)/(double)stats.Sum(s=>s.PassAttempts),YardsPerRush=stats.Sum(s=>s.RushYards)/(double)stats.Sum(s=>s.RushAttempts),PassAttempts=Mean(s=>s.PassAttempts),RushAttempts=Mean(s=>s.RushAttempts),Sacks=Mean(s=>s.SacksAllowed),Turnovers=Mean(s=>s.Turnovers),PrimaryQBSnapShare=qbShares.Average(),LeadRBCarryShare=rbShares.Average(),ThirdAndLaterRBCarryShare=rb3.Average(),BackupDLSnapShare=dlShares.Average(),MalformedPersonnelSnaps=malformed,DuplicatePersonnelSnaps=duplicate,BadExamples=badExamples};
var json=JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true});Directory.CreateDirectory(Path.GetDirectoryName(output)!);File.WriteAllText(output,json);Console.WriteLine(json);
